(() => {
 const articles=JSON.parse(document.getElementById('knowledge-data').textContent),form=document.getElementById('knowledge-search'),input=document.getElementById('knowledge-query'),cards=[...document.querySelectorAll('[data-entry]')],result=document.getElementById('knowledge-result'),pages=document.getElementById('knowledge-pages');
 const en=document.documentElement.lang!=='vi',tr=(vi,enText)=>en?(document.documentElement.lang.startsWith('zh')?HOTPRINT_I18N.translate(enText):enText):vi,allowed=new Set(['all','structure','materials','artwork','process']);
 const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').toLowerCase();
 const tokens=s=>normalize(s).match(/[a-z0-9]+|[\u3400-\u9fff]+/g)||[],index=new Map(articles.map(a=>[a.id,new Set(tokens(a.search.join(' ')))]));
 let state;const pageSize=9;
 function read(){const p=new URLSearchParams(location.search);state={q:(p.get('q')||'').slice(0,150),topic:allowed.has(p.get('topic'))?p.get('topic'):'all',page:Math.max(1,Math.floor(Number(p.get('page')))||1)};input.value=state.q}
 function render(push=false){const words=tokens(state.q.trim()),matches=articles.filter(a=>(state.topic==='all'||a.topic===state.topic)&&words.every(w=>/[\u3400-\u9fff]/.test(w)?[...index.get(a.id)].some(term=>term.includes(w)):index.get(a.id).has(w))),count=Math.max(1,Math.ceil(matches.length/pageSize));state.page=Math.min(state.page,count);
  const visible=new Set(matches.slice((state.page-1)*pageSize,state.page*pageSize).map(a=>a.id));cards.forEach(c=>c.hidden=!visible.has(c.dataset.entry));document.getElementById('knowledge-empty').hidden=!!matches.length;
  result.textContent=matches.length+' '+tr('bài hướng dẫn','guide'+(matches.length===1?'':'s'))+(state.q.trim()?tr(' cho “',' for “')+state.q.trim()+'”':'');document.getElementById('knowledge-reset').hidden=!state.q&&state.topic==='all';document.querySelectorAll('[data-topic]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.topic===state.topic)));
  pages.replaceChildren();pages.hidden=count<2;for(let n=1;n<=count;n++){const b=document.createElement('button');b.type='button';b.textContent=n;b.setAttribute('aria-label',tr('Trang ','Page ')+n);if(n===state.page)b.setAttribute('aria-current','page');b.onclick=()=>{state.page=n;render(true);document.getElementById('kp-library-title').scrollIntoView({block:'start'})};pages.append(b)}
  const url=new URL(location.href);for(const [key,value]of [['q',state.q.trim()],['topic',state.topic==='all'?'':state.topic],['page',state.page===1?'':String(state.page)]])value?url.searchParams.set(key,value):url.searchParams.delete(key);history[push?'pushState':'replaceState']({},'',url.pathname+url.search+url.hash);document.querySelectorAll('[data-lang]').forEach(a=>a.href=HOTPRINT_I18N.path('/en/packaging-insights/','/kien-thuc/',a.dataset.lang)+url.search+url.hash);
 }
 form.addEventListener('submit',e=>{e.preventDefault();state.q=input.value.trim();state.page=1;render(true)});document.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{state.topic=b.dataset.topic;state.q=input.value.trim();state.page=1;render(true)}));document.getElementById('knowledge-reset').onclick=()=>{state={q:'',topic:'all',page:1};input.value='';render(true);input.focus()};window.addEventListener('popstate',()=>{read();render()});read();render();
})();
